def sha(raw):
    return hashlib.sha256(raw).hexdigest()


def functions(raw):
    tree=ast.parse(raw)
    answer={}
    for node in tree.body:
        if isinstance(node,ast.FunctionDef):
            answer[node.name]=ast.dump(node,include_attributes=False)
        elif isinstance(node,ast.ClassDef):
            for method in node.body:
                if isinstance(method,ast.FunctionDef):
                    answer[node.name+'.'+method.name]=ast.dump(method,include_attributes=False)
    return answer


def syntax(raw,name):
    if not 0<len(raw)<100000:
        raise ValueError('Every complete inspectable source stays below100000 bytes')
    text=raw.decode()
    if any(line.rstrip()!=line for line in text.splitlines()):
        raise ValueError('Trailing source whitespace')
    tree=ast.parse(text)
    compile(tree,name,'exec')
    for node in ast.walk(tree):
        if not isinstance(node,ast.Dict):
            continue
        known=set()
        for key in node.keys:
            if key is None:
                continue
            try:
                value=ast.literal_eval(key)
                hash(value)
            except (ValueError,TypeError):
                continue
            if value in known:
                raise ValueError('Duplicate literal dictionary key')
            known.add(value)


def reconstruct(parent,spec):
    if len(parent)!=spec['parent_bytes'] or sha(parent)!=spec['parent_sha256']:
        raise ValueError('The entire original parent source differs: '+spec['parent_name'])
    chunks=[]
